def route(query, candidates, quality_fn, cost_fn, lam=0.5):
    scores = {m: quality_fn(query, m) - lam * cost_fn(query, m)
              for m in candidates}
    return max(scores, key=scores.get)

# RouteFM：quality_fn 由冻结路由器加行为上下文给出，新候选无需重训

def chinchilla_loss(N, D, E=1.69, A=406.4, B=410.7, alpha=0.34, beta=0.28):
    return E + A / N ** alpha + B / D ** beta

print(chinchilla_loss(1e9, 2e10))

def build_bank(history, poses, K=8, covis=None):
    # history: [T, d] 历史 latent；poses: 末 k 个计分 chunk 的相机位姿
    bank = {}
    for p in poses:
        top = sorted(range(len(history)), key=lambda i: -covis(p, i))[:K]
        for i in top:
            bank[i] = history[i]
    assert len(bank) <= K * len(poses)  # 上界 kK
    return list(bank.values())
